def rail_fence_encrypt(text, rails):
    if rails == 1:
        return text
    fence = [''] * rails
    rail = 0
    direction = 1  # 1 = down, -1 = up
    for char in text:
        fence[rail] += char
        rail += direction
        if rail == 0 or rail == rails - 1:
            direction *= -1
    return ''.join(fence)
